@OptIn(ExperimentalStdlibApi::class)
private fun getCacheFile(key: CacheKey<KeyType>): File {
	val md = MessageDigest.getInstance("MD5")
	return File(cacheDir, md.digest(key.toString().toByteArray()).toHexString())
}

